-- site_signals: JSON read off a company's verified website and the Wayback index: its careers
-- page and roughly how many role titles it lists (or the hiring platform it links to), a team
-- page, a code account named like the site, whether the homepage reads as parked or for sale,
-- and how many distinct homepage versions the archive kept over two years. Facts about the
-- site, not the company. NULL: not read yet. ingest/sitepages.py and wayback.activity.
ALTER TABLE companies ADD COLUMN site_signals TEXT;

